-- ============================================================
-- Hidden Gems & Content Enrichment — Data Migration
-- 2026-07-09
--
-- Inserts 12 hidden gem destinations with full content from
-- the comprehensive SEO/destination research.
-- Also enriches Minneriya (already partially in system).
--
-- Safe to re-run: uses INSERT ... WHERE NOT EXISTS guards.
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ════════════════════════════════════════════════════════════
-- Helper: insert destination if slug doesn't exist yet
-- ════════════════════════════════════════════════════════════

DROP PROCEDURE IF EXISTS ict_insert_dest_if_missing;
DELIMITER //
CREATE PROCEDURE ict_insert_dest_if_missing(
    p_name VARCHAR(150),
    p_slug VARCHAR(180),
    p_excerpt VARCHAR(500),
    p_intro LONGTEXT,
    p_why_visit LONGTEXT,
    p_things_to_do LONGTEXT,
    p_best_time LONGTEXT,
    p_how_to_get_there LONGTEXT,
    p_suggested_itinerary LONGTEXT,
    p_where_to_stay LONGTEXT,
    p_travel_tips LONGTEXT,
    p_faq_json LONGTEXT,
    p_cta_title VARCHAR(255),
    p_cta_text TEXT,
    p_province VARCHAR(200),
    p_temperature VARCHAR(60),
    p_destination_type VARCHAR(120),
    p_recommended_stay VARCHAR(80),
    p_stay_duration VARCHAR(80),
    p_region_slug VARCHAR(60),
    p_region_label VARCHAR(120),
    p_emoji VARCHAR(16),
    p_map_x DECIMAL(6,2),
    p_map_y DECIMAL(6,2),
    p_map_r DECIMAL(4,1),
    p_map_initial VARCHAR(4),
    p_meta_title VARCHAR(255),
    p_meta_description VARCHAR(320),
    p_sort_order INT,
    p_is_published TINYINT,
    p_is_hidden_gem TINYINT,
    p_hidden_gem_category VARCHAR(60),
    p_best_known_for VARCHAR(255),
    p_works_well_with TEXT,
    p_nearby_travel_times TEXT,
    p_peak_season_json LONGTEXT,
    p_best_season_label VARCHAR(120),
    p_shoulder_season_label VARCHAR(120),
    p_off_season_label VARCHAR(120),
    p_weather_summary VARCHAR(255),
    p_season_start VARCHAR(10),
    p_season_end VARCHAR(10),
    p_demographic_json LONGTEXT,
    p_platform_ratings_json LONGTEXT,
    p_difficulty_level VARCHAR(30),
    p_access_type VARCHAR(60),
    p_crowd_level VARCHAR(30),
    p_logistical_notes TEXT,
    p_nearby_highlights_json LONGTEXT,
    p_route_pairing_json LONGTEXT
)
BEGIN
    DECLARE existing_id BIGINT UNSIGNED DEFAULT NULL;
    SELECT id INTO existing_id FROM destinations WHERE slug = p_slug LIMIT 1;

    IF existing_id IS NULL THEN
        INSERT INTO destinations (
            name, slug, excerpt, intro, why_visit, things_to_do,
            best_time, how_to_get_there, suggested_itinerary, where_to_stay,
            travel_tips, faq_json, cta_title, cta_text,
            province, temperature, destination_type, recommended_stay,
            stay_duration, region_slug, region_label, emoji,
            map_x, map_y, map_r, map_initial,
            meta_title, meta_description,
            sort_order, is_published, is_hidden_gem, hidden_gem_category, best_known_for,
            works_well_with, nearby_travel_times,
            peak_season_json, best_season_label, shoulder_season_label, off_season_label,
            weather_summary, season_start, season_end,
            demographic_json, platform_ratings_json,
            difficulty_level, access_type, crowd_level, logistical_notes,
            nearby_highlights_json, route_pairing_json
        ) VALUES (
            p_name, p_slug, p_excerpt, p_intro, p_why_visit, p_things_to_do,
            p_best_time, p_how_to_get_there, p_suggested_itinerary, p_where_to_stay,
            p_travel_tips, p_faq_json, p_cta_title, p_cta_text,
            p_province, p_temperature, p_destination_type, p_recommended_stay,
            p_stay_duration, p_region_slug, p_region_label, p_emoji,
            p_map_x, p_map_y, p_map_r, p_map_initial,
            p_meta_title, p_meta_description,
            p_sort_order, p_is_published, p_is_hidden_gem, p_hidden_gem_category, p_best_known_for,
            p_works_well_with, p_nearby_travel_times,
            p_peak_season_json, p_best_season_label, p_shoulder_season_label, p_off_season_label,
            p_weather_summary, p_season_start, p_season_end,
            p_demographic_json, p_platform_ratings_json,
            p_difficulty_level, p_access_type, p_crowd_level, p_logistical_notes,
            p_nearby_highlights_json, p_route_pairing_json
        );
    END IF;
END//
DELIMITER ;

-- ════════════════════════════════════════════════════════════
-- 1. SINHARAJA FOREST RESERVE
-- ════════════════════════════════════════════════════════════

CALL ict_insert_dest_if_missing(
    'Sinharaja Forest Reserve',
    'sinharaja',
    'A UNESCO World Heritage rainforest teeming with endemic birds, ancient trees, and hidden waterfalls — Sri Lanka\'s last great lowland rainforest.',
    'Sinharaja is Sri Lanka\'s last viable area of primary tropical rainforest. It sprawls across 11,000 hectares of the south-west wet zone, a UNESCO World Heritage Site and a biosphere reserve, recognized globally for its extraordinary biodiversity. Over 60% of the trees are endemic. More than 95% of the amphibians and 50% of the mammals are found nowhere else on earth. The canopy rises 45 metres above the forest floor, filtering the sunlight into a perpetual green twilight. Mist rolls through the valleys. Waterfalls drop into clear pools. And the sounds — birds, insects, the rustle of leaves — are constant. It is not an easy visit. The trails are muddy, the leeches are persistent, and the humidity is relentless. But for anyone who cares about nature, Sinharaja is essential.',
    'Sinharaja is about the birds. The Sri Lanka Blue Magpie, the Red-faced Malkoha, the Serendib Scops-Owl — these are names that birders travel across the world to tick. But even non-birders will be awed by the scale of the forest. The trees are enormous. The buttress roots spread like walls. The vines and epiphytes create a layered ecosystem that feels prehistoric. The guided walks into the forest are led by local trackers who know every bird call, every medicinal plant, every ridge that leads to a waterfall. It is immersive, educational, and humbling. This is what Sri Lanka looked like before the plantations.',
    'Join a guided early-morning bird walk (start at 6 AM for the best bird activity). Walk the main Sinharaja loop through the reserve (2-3 hours, moderate difficulty). Visit the waterfall near the entrance — a 20-minute walk through the forest. Spot endemic birds: Sri Lanka Blue Magpie, Red-faced Malkoha, Sri Lanka Spurfowl. Learn about medicinal plants from your guide. Photograph the canopy from the viewing platform. Visit the research centre near the entrance. Trek deeper into the reserve on a full-day hike (advanced, requires a dedicated guide).',
    'Sinharaja can rain any day of the year, but the driest and best months are January to March and August to September. The forest is at its most active in the early morning; by midday the birds go quiet. The leeches are worst in the wet season (May-July). Visit in the dry season for easier trails.',
    'About 110 kilometres from Colombo — 3 hours by car via Ratnapura or Kalawana. The road winds through tea and rubber plantations. The last 8 kilometres are unpaved and rough — a private car or 4WD is recommended. Buses run from Colombo to Kalawana, from where you can arrange a tuk-tuk to the reserve entrance.',
    'One night is enough for the highlights. Day one: arrive by midday, afternoon guided walk. Day two: early-morning bird walk, leave by lunch. Serious birders should stay two or three nights for multiple walks at different elevations.',
    'Accommodation is clustered around the reserve entrances (Kudawa, Lankagama, and Pitadeniya). The eco-lodges are basic but clean: Blue Magpie Lodge is the best-known. Rainforest Eco Lodge is comfortable. For budget, several homestays operate near the Kudawa entrance. None are luxury. That is not the point of Sinharaja.',
    'Book a guide in advance — it is mandatory and enforced. Wear long trousers and gaiters for leeches. Buy leech socks from the entrance shop. The trails are slippery after rain. Carry water and a small backpack. The humidity is extreme — expect to sweat through your clothes within minutes. No plastic bottles are allowed inside the reserve. Do not touch or disturb the wildlife.',
    '[{"q":"Do I need a guide for Sinharaja?","a":"Yes. All visitors must be accompanied by a local tracker. It is a Strict Nature Reserve regulation and the guides are excellent at spotting wildlife."},{"q":"Are the leeches really that bad?","a":"Yes, especially in the wet season. Wear leech socks and long trousers. Treat it as part of the experience."},{"q":"Can I visit Sinharaja on a day trip from Colombo?","a":"Technically yes, but the drive is 3 hours each way. An overnight stay is strongly recommended."}]',
    'Plan Your Sinharaja Rainforest Experience',
    'We can arrange a private guide and transport for your Sinharaja rainforest trek — including leech socks and a packed lunch.',
    'Sabaragamuwa Province',
    '24–30°C',
    'Rainforest / UNESCO',
    '1–2 Days',
    '1–2 days',
    'wildlife',
    'Wildlife',
    '🌳',
    90, 258, 6.5, 'Si',
    'Sinharaja Forest Reserve Travel Guide | Island Culture Travels',
    'Plan a Sinharaja rainforest trek with private guide, endemic birding, waterfall walks, and UNESCO biodiversity. Private transfers from Colombo.',
    50, 1, 1, 'Rainforest / UNESCO',
    'UNESCO rainforest trekking with endemic birds and pristine jungle',
    'Udawalawe, Ratnapura, Kitulgala, Galle',
    'Ratnapura: 1.5 hrs. Kalawana: 45 min. Udawalawe: 2 hrs. Colombo: 3 hrs.',
    '{"months":[{"month":"Jan","rating":"great"},{"month":"Feb","rating":"great"},{"month":"Mar","rating":"great"},{"month":"Apr","rating":"okay"},{"month":"May","rating":"avoid"},{"month":"Jun","rating":"avoid"},{"month":"Jul","rating":"avoid"},{"month":"Aug","rating":"great"},{"month":"Sep","rating":"great"},{"month":"Oct","rating":"okay"},{"month":"Nov","rating":"avoid"},{"month":"Dec","rating":"okay"}],"note":"Best Jan-Mar and Aug-Sep for fewer leeches and better trail conditions."}',
    'Jan–Mar, Aug–Sep',
    'Apr, Oct',
    'May–Jul',
    'Humid and lush. Rain can fall any day; driest Jan-Mar and Aug-Sep.',
    'Jan',
    'Mar',
    '{"nationalities":["UK","GER","AUS"],"top_activities":["Bird watching (Blue Magpie)","Guided forest treks","Waterfall dips","Photography"],"traveler_types":["nature","photographer","birder","eco"]}',
    '[{"platform":"TripAdvisor","score":"4.5","url":"","notes":"Highly rated for guided forest experiences"},{"platform":"Booking.com","score":"8.8","reviews":"Eco-lodges nearby","url":""}]',
    'Moderate',
    'Car (4x4 recommended)',
    'Quiet',
    'Strict Regulations: Must hire a local guide — mandatory. Seasonality: Leeches are a major issue in wet months; requires gaiters. Logistical Effort: Remote; requires a dedicated detour from the main Colombo–Galle route.',
    '[{"name":"Udawalawe","slug":"udawalawe","type":"wildlife","distance":"2 hrs"},{"name":"Ratnapura","slug":"ratnapura","type":"city","distance":"1.5 hrs"},{"name":"Kitulgala","slug":"kitulgala","type":"adventure","distance":"2 hrs"}]',
