    '{"nationalities":["UK","FRA"],"top_activities":["Wild horse photography","Baobab tree visits","Ruins exploration","Ferry rides","Coral fence walks"],"traveler_types":["adventure","photographer","solo","culture"]}',
    '[{"platform":"TripAdvisor","score":"4.0","url":"","notes":"Unique off-the-beaten-path experience"}]',
