    '[{"name":"Casuarina Beach","type":"beach","distance":"east coast"},{"name":"Dutch Fort","type":"heritage","distance":"south coast"},{"name":"Point Pedro","slug":"point-pedro","type":"heritage","distance":"45 min + ferry"}]',
