SELECT CONCAT('Inserted/verified ', COUNT(*), ' destinations') AS result
FROM destinations
WHERE slug IN (
    'sinharaja','haputale','wilpattu','kalpitiya','gal-oya',
    'ritigala','ussangoda','yapahuwa','minneriya','delft-island',
    'bundala','meemure'
);
